/**
 * Measured figures behind the implementation page.
 *
 * Generated by `npm run db:stats -- --facts`, which queries the live index and
 * runs the real embedding model. Committed rather than computed at request time
 * so the page is a static document that costs no database round trips to render.
 *
 * Every number on the page comes from here. The page has no hard-coded figures,
 * so it cannot quietly disagree with the system it describes - and when it does
 * disagree, regenerating this file is the fix.
 */
export interface CorpusFact {
  source: string;
  passages: number;
  medianChars: number;
  maxChars: number;
}

export interface Facts {
  corpus: CorpusFact[];
  sizes: { relname: string; bytes: number; n_live_tup: number }[];
  indexes: { name: string; bytes: number }[];
  database: { bytes: number };
  scoreSeparation: {
    relevant: { min: number; p05: number; p25: number; median: number; p75: number; max: number; count: number };
    offTopic: { max: number; median: number; p95: number; count: number };
  };
  thresholdSweep: { threshold: number; relevantPerQuery: number; offTopicPerQuery: number }[];
  /**
   * Where a query's time actually goes, measured separately because the two
   * costs have different causes and different fixes. A single end-to-end
   * number hides which one is slow.
   */
  latency: {
    modelLoadMs: number;
    embedWarmMs: number;
    sqlMedianMs: number;
    deployedColdMs: number;
    deployedWarmMs: number;
    deployedServerMedianMs: number;
    deployedEmptyMs: number;
  };
  /** Rank of the correct passage, before and after adding the lexical retriever. */
  rankingChange: { question: string; before: number; after: number; section: string };
  /** The threshold the system actually ships with. */
  threshold: number;
  /** Version of the file the measurements describe. */
  generated: string;
}

